function ajouterPlaces(fiches, ajout) {
  for (const fiche of fiches) { fiche.places = fiche.places + ajout; }
  return fiches;
}

exercises.solution:
function ajouterPlaces(fiches, ajout) {
  const resultat = [];
  for (const fiche of fiches) {
    resultat.push({ ...fiche, places: fiche.places + ajout });
  }
  return resultat;
}

